import { createAppAuth } from "@octokit/auth-app";

// appId and privateKey come from the pod's secret (Vault via ExternalSecrets), never from the VM
const auth = createAppAuth({ appId, privateKey });

export const tokenForRun = async (installationId: number) => {
  const { token, expiresAt } = await auth({
    type: "installation",
    installationId,
    repositoryNames: ["fcp"],
    permissions: { contents: "write", pull_requests: "write", checks: "read", actions: "read" }, // never "workflows"
  });
  return { token, expiresAt }; // one hour; the broker uses it, the VM never holds it
};
